    let part = match claim_term(expr, words, &mut &mut *var, &mut &mut *pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return };
    if holds { parts.push(part); } else { parts.push(built(logic::SolverTerm::Not(part), out)); }
